python3 -c "
import pathlib
p = pathlib.Path('tests/codegen/objects/gc_aliasing.rs')
t = p.read_text()
old = '''echo \$filtered[0][1] . \"|\" . \$filtered[1][0];
\"#,
    );
    assert_eq!(out, \"11|2\");'''
new = '''echo (\$filtered[1][1] ?? \"-\") . \"|\" . (\$filtered[2][0] ?? \"-\");
\"#,
    );
    // php's array_filter() PRESERVES keys, so the survivors of a three-element list are at 1 and
    // 2, not 0 and 1. Measured: \`php -n\` prints the same \`11|2\` through those keys, and answers
    // \`array_keys()\` = [1, 2].
    assert_eq!(out, \"11|2\");'''
assert t.count(old) == 1, 'not found'
p.write_text(t.replace(old, new, 1))
print('gc_aliasing.rs: the test reads the keys php preserves')
